using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;
using System.ComponentModel;
using System.Text.Json;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = "gpt-4o-mini-2024-07-18";

IChatClient innerClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notes = new ResearchNotes();

var tools = new object[] { new WebSearchTool(), notes };

IChatClient chatClient = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Given a topic, search the web for information, "
    + "take notes on key findings, then provide a final summary. "
    + "Use the web_search tool to find information and the add_note tool to record findings. "
    + "Search multiple queries to get comprehensive results, take notes, then summarize.");

Console.WriteLine("Research Agent Ready!");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. tools.SelectMany(AIFunctionFactory.Create)],
};

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly. Search for multiple aspects, "
        + $"take notes on your findings, and then provide a comprehensive summary.\n\nTopic: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes Collected ---");
foreach (var note in notes.GetAllNotes())
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

[Description("Searches the web for information on a query and returns results.")]
sealed class WebSearchTool
{
    [AIFunction, Description("Search the web for information. Returns a list of result snippets.")]
    public static string WebSearch(
        [Description("The search query")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // Replace with a real search API (Bing, Google, etc.) in production.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        var simulatedResults = new[]
        {
            $"Result 1 for '{query}': Recent studies indicate significant developments in this area. "
            + "Researchers have published multiple findings in 2025-2026 showing promising progress.",
            $"Result 2 for '{query}': According to industry experts, the key challenges include "
            + "scalability, cost-effectiveness, and integration with existing systems.",
            $"Result 3 for '{query}': A 2026 report highlights that adoption has grown 40% year-over-year, "
            + "with particular strength in enterprise and healthcare sectors.",
        };

        return string.Join("\n\n", simulatedResults);
    }
}

[Description("A note-taking tool for recording research findings.")]
sealed class ResearchNotes
{
    private readonly List<string> _notes = [];

    [AIFunction, Description("Add a research note to record an important finding.")]
    public string AddNote(
        [Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note recorded ({_notes.Count} total)");
        return $"Note recorded successfully. Total notes: {_notes.Count}";
    }

    [AIFunction, Description("Retrieve all notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes recorded yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public IReadOnlyList<string> GetAllNotes() => _notes;
}

